-- 200 spell_dbc rows for the mod-kill-tracker milestone (tier) buff system
-- (tiers 1-100). Each tier N is an INDEPENDENT pair of passive spells
-- (permanent, granted via learnSpell, never removed — the player
-- accumulates every tier passed so far):
--   Spell A = 900500+(N-1): +100 armor (aura 22 MOD_RESISTANCE, misc=1
--             physical), +50 melee attack power (aura 99), +50 ranged
--             attack power (aura 124)
--   Spell B = 900700+(N-1): +50 spell power (aura 13 MOD_DAMAGE_DONE,
--             misc=126 - all schools), +3% melee/ranged attack speed
--             (aura 192), +3% casting speed (aura 216)
-- Every tier carries the SAME flat value — the total bonus at tier N is the
-- natural sum: N*100 armor / N*50 AP / N*50 SP / N*3% haste.
-- Attributes=64 = SPELL_ATTR0_PASSIVE. EquippedItemClass/Subclass/InvTypes=-1
-- is required (0 is the real ITEM_CLASS_CONSUMABLE and blocks the effect).
DELETE FROM `spell_dbc` WHERE `ID` BETWEEN 900500 AND 900599;
DELETE FROM `spell_dbc` WHERE `ID` BETWEEN 900700 AND 900799;
INSERT INTO `spell_dbc`
    (`ID`, `Attributes`, `EquippedItemClass`, `EquippedItemSubclass`, `EquippedItemInvTypes`,
     `Effect_1`, `EffectBasePoints_1`, `EffectAura_1`, `EffectMiscValue_1`, `ImplicitTargetA_1`,
     `Effect_2`, `EffectBasePoints_2`, `EffectAura_2`, `EffectMiscValue_2`, `ImplicitTargetA_2`,
     `Effect_3`, `EffectBasePoints_3`, `EffectAura_3`, `EffectMiscValue_3`, `ImplicitTargetA_3`,
     `SpellIconID`, `Name_Lang_enUS`, `Name_Lang_ruRU`, `Name_Lang_Mask`)
